package local.skyfamily;
import android.graphics.*;import android.media.MediaPlayer;import android.net.Uri;import android.os.Handler;import android.view.*;import android.widget.*;import java.net.*;import java.util.*;
public class CastActivity extends AlbumsActivity {
 UpnpRenderer renderer;final Handler castUI=new Handler();FrameLayout castStage;TextView castTitle,castStatus;VideoView castVideo;MediaPlayer castMedia;int session=0,load=0;boolean castReady=false;SeekBar castSeek;
 @Override void home(){super.home();button("Cast receiver / DLNA",()->castSetup());}
 @Override void page(String title){stopReceiver();super.page(title);}
 void castSetup(){page("Cast receiver");text("Receive music, photos and videos from a DLNA/UPnP controller on the same reachable LAN. Not Miracast, Google Cast or AirPlay. Receiver runs only while this app's receiving screen is active.");text("Trusted network only: DLNA has no pairing/password here. Local devices can choose playback URLs and control playback while enabled. Do not forward ports to the Internet. The receiver fetches the HTTP(S) media URL supplied by the sender; files are not automatically imported into Immich or the gallery.");EditText name=input("Receiver name",get("dlna.name").isEmpty()?"Sky Family Frame":get("dlna.name"));try{Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();int count=0;while(interfaces.hasMoreElements()){NetworkInterface net=interfaces.nextElement();if(!net.isUp()||net.isLoopback())continue;Enumeration<InetAddress> addresses=net.getInetAddresses();while(addresses.hasMoreElements()){InetAddress ip=addresses.nextElement();if(ip instanceof Inet4Address&&ip.isSiteLocalAddress()){button("Enable receiving on "+ip.getHostAddress(),()->{String value=name.getText().toString().trim();if(value.isEmpty()||value.length()>64){toast("Enter a device name of 1-64 characters");return;}save("dlna.name",value);beginReceiver(ip,value);});count++;}}}if(count==0)text("No private IPv4 address found. Connect to your home network first.");}catch(Exception e){text("Network interface unavailable: "+e.getMessage());}}
 void beginReceiver(InetAddress ip,String name){page("Receiving media");final int generation=++session;try{String id=get("dlna.uuid");if(id.isEmpty()){id=UUID.randomUUID().toString();save("dlna.uuid",id);}renderer=new UpnpRenderer(getApplicationContext(),ip,name,id,(action,args)->castUI.post(()->{if(renderer!=null&&session==generation)castCommand(action,args);}));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.BLACK);LinearLayout top=new LinearLayout(this);root.addView(top,new LinearLayout.LayoutParams(-1,dp(54)));iconControl(top,"Stop receiver",()->home());iconControl(top,"Rotate",()->screenRotation());castTitle=new TextView(this);castTitle.setText(name);castTitle.setTextColor(fg);castTitle.setTextSize(24);castTitle.setPadding(dp(18),dp(12),dp(18),dp(8));root.addView(castTitle);castStatus=new TextView(this);castStatus.setText("Discoverable on "+ip.getHostAddress()+" / select this frame in a DLNA controller");castStatus.setTextColor(accent);castStatus.setPadding(dp(18),0,dp(18),dp(12));root.addView(castStatus);castStage=new FrameLayout(this);root.addView(castStage,new LinearLayout.LayoutParams(-1,0,1));castSeek=new SeekBar(this);root.addView(castSeek);castSeek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&castReady&&castVideo!=null)castVideo.seekTo(value);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});LinearLayout controls=new LinearLayout(this);root.addView(controls,new LinearLayout.LayoutParams(-1,dp(56)));iconControl(controls,"Play",()->local("Play"));iconControl(controls,"Pause",()->local("Pause"));iconControl(controls,"Stop",()->local("Stop"));iconControl(controls,"Mute",()->{if(renderer!=null){renderer.muted=!renderer.muted;applyVolume();}});SeekBar volume=new SeekBar(this);volume.setMax(100);volume.setProgress(100);root.addView(volume);volume.setContentDescription("Playback volume");volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int n,boolean user){if(user&&renderer!=null){renderer.volume=n;applyVolume();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});setContentView(root);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);immersive();castUI.post(tickCast);}catch(Exception e){stopReceiver();text("Could not enable receiver: "+e.getMessage());}}
 void local(String action){if(renderer==null)return;try{HashMap<String,String> args=new HashMap<>();args.put("InstanceID","0");if(action.equals("Play"))args.put("Speed","1");renderer.act("avt",action,args);}catch(Exception e){toast("No playable media has been received");}}
 void castCommand(String action,Map<String,String> args){if(action.equals("SetAVTransportURI")){receiveMedia(args.get("CurrentURI"),args.get("CurrentURIMetaData"));return;}if(action.equals("Play")&&castReady&&castVideo!=null)castVideo.start();if(action.equals("Pause")&&castVideo!=null)castVideo.pause();if(action.equals("Stop")&&castVideo!=null){castVideo.pause();castVideo.seekTo(0);}if(action.equals("Seek")&&castReady&&castVideo!=null)castVideo.seekTo((int)Math.min(Integer.MAX_VALUE,renderer.position));if(action.equals("SetVolume")||action.equals("SetMute"))applyVolume();if(castStatus!=null)castStatus.setText(renderer.state);}
 void applyVolume(){if(castMedia!=null&&renderer!=null)try{float v=renderer.muted?0:renderer.volume/100f;castMedia.setVolume(v,v);}catch(Exception ignored){}}
 void receiveMedia(String address,String metadata){final int stamp=++load;final int generation=session;castReady=false;if(castVideo!=null){castVideo.stopPlayback();castVideo=null;}castMedia=null;castStage.removeAllViews();String title="Received media",mime="";if(metadata!=null&&!metadata.isEmpty())try{Map<String,String> values=UpnpRenderer.parse(metadata);if(values.containsKey("title"))title=values.get("title");if(metadata.contains("image/"))mime="image";else if(metadata.contains("audio/"))mime="audio";}catch(Exception ignored){}String path=Uri.parse(address).getPath();path=path==null?"":path.toLowerCase(Locale.US);boolean photo=mime.equals("image")||path.endsWith(".jpg")||path.endsWith(".jpeg")||path.endsWith(".png")||path.endsWith(".gif");boolean audio=mime.equals("audio")||path.endsWith(".mp3")||path.endsWith(".m4a")||path.endsWith(".aac")||path.endsWith(".wav")||path.endsWith(".ogg");castTitle.setText(title);castStatus.setText(photo?"Loading photo...":audio?"Preparing music...":"Preparing video...");if(photo){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);castStage.addView(image,new FrameLayout.LayoutParams(-1,-1));work(()->{try{Bitmap bitmap=bitmap(request(address,"GET",null,"",20000000));if(bitmap==null)throw new java.io.IOException("Unsupported image");castUI.post(()->{if(renderer==null||generation!=session||stamp!=load){bitmap.recycle();return;}image.setImageBitmap(bitmap);castReady=true;renderer.state=renderer.wantPlay?"PLAYING":"STOPPED";castStatus.setText(renderer.state+" / Photo / sender controls changes");});}catch(Exception e){castUI.post(()->mediaError(generation,stamp,"Unable to display the received photo"));}});return;}final VideoView video=new VideoView(this);castVideo=video;castStage.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));if(audio){TextView music=new TextView(this);music.setText("NOW PLAYING\n"+title);music.setTextSize(30);music.setTextColor(fg);music.setGravity(Gravity.CENTER);castStage.addView(music,new FrameLayout.LayoutParams(-1,-1));}video.setOnPreparedListener(mp->{if(renderer==null||generation!=session||stamp!=load)return;castMedia=mp;castReady=true;renderer.duration=Math.max(0,mp.getDuration());renderer.state=renderer.wantPlay?"PLAYING":"STOPPED";applyVolume();if(renderer.wantPlay)video.start();castStatus.setText(renderer.state);});video.setOnCompletionListener(mp->{if(renderer!=null&&generation==session&&stamp==load){renderer.state="STOPPED";renderer.wantPlay=false;castStatus.setText("Playback finished");}});video.setOnErrorListener((mp,what,extra)->{mediaError(generation,stamp,"Cannot play this format, URL or stream on the frame");return true;});video.setVideoURI(Uri.parse(address));}
 void mediaError(int generation,int stamp,String message){if(renderer==null||generation!=session||stamp!=load)return;renderer.state="STOPPED";renderer.status="ERROR_OCCURRED";renderer.wantPlay=false;castStatus.setText(message);}
 final Runnable tickCast=new Runnable(){public void run(){if(renderer==null)return;if(castVideo!=null&&castReady)try{renderer.position=Math.max(0,castVideo.getCurrentPosition());renderer.duration=Math.max(0,castVideo.getDuration());castSeek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(1,renderer.duration)));castSeek.setProgress((int)Math.min(Integer.MAX_VALUE,renderer.position));}catch(Exception ignored){}castUI.postDelayed(this,500);}};
 void stopReceiver(){session++;load++;castUI.removeCallbacksAndMessages(null);if(castVideo!=null){castVideo.stopPlayback();castVideo=null;}castMedia=null;castReady=false;if(renderer!=null){renderer.close();renderer=null;}getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 @Override public void onBackPressed(){if(renderer!=null){stopReceiver();home();}else super.onBackPressed();}
 @Override protected void onPause(){stopReceiver();if(castStatus!=null)castStatus.setText("Receiver stopped / reopen Cast receiver to enable it");super.onPause();}
 @Override protected void onDestroy(){stopReceiver();super.onDestroy();}
}
